insert into categories (id, name, tagline, descr, img, color, sort) values
  ('draje', '{"uz":"Draje","ru":"Драже","en":"Dragee"}', '{"uz":"Yaltiroq qobiqli mayda shirinliklar","ru":"Маленькие сладости в глянцевой глазури","en":"Small sweets in a glossy shell"}', '{"uz":"Draje konfetlar — kichkina, lekin yorqin shirinliklar. Qarsillab turuvchi qobiq ostida shokolad, yeryong‘oq, mevali yoki karamel ichligi yashiringan.","ru":"Конфеты драже — маленькие, но яркие сладости в глазури. Хрустящая оболочка скрывает шоколад, орехи, фруктовые или карамельные начинки.","en":"Dragee sweets — small but vivid. A crisp shell hides chocolate, peanuts, fruit or caramel centres."}', 'assets/img/photo/nati.jpg', 'brand', 0),
  ('nachinka', '{"uz":"Ichlikli konfetlar","ru":"Конфеты с начинкой","en":"Filled sweets"}', '{"uz":"Shokolad va nozik ichlik uyg‘unligi","ru":"Нежное сочетание шоколада и начинки","en":"Chocolate meets a soft centre"}', '{"uz":"Ichlikli konfetlar — shokolad va nafis ichlikning nozik uyg‘unligi. Har bir konfetda yong‘oq, karamel, meva pyuresi yoki krem ta’mi yashiringan.","ru":"Конфеты с начинкой — нежное сочетание шоколада и изысканной начинки: орехи, карамель, фруктовое пюре или крем.","en":"Filled sweets — a soft pairing of chocolate and a refined centre: nuts, caramel, fruit purée or cream."}', 'assets/img/photo/Royal.jpg', 'gold', 10),
  ('dekor', '{"uz":"Dekorativ sepmalar","ru":"Декоративные посыпки","en":"Decorative toppings"}', '{"uz":"Tort va desertlar uchun bezak","ru":"Украшение для тортов и десертов","en":"Finishing touch for cakes and desserts"}', '{"uz":"Qandolat sepmalari — tort, kapkeyk va desertlarni bezash uchun rangli vermishel va sharchalar. Rang barqarorligi va bir xil o‘lchami bilan ajralib turadi.","ru":"Кондитерские посыпки — цветная вермишель и шарики для украшения тортов, капкейков и десертов. Стойкий цвет и ровный калибр.","en":"Confectionery sprinkles — coloured vermicelli and beads for cakes, cupcakes and desserts. Stable colour, even calibre."}', 'assets/img/photo/stick.jpg', 'mint', 20),
  ('zavtrak', '{"uz":"Tayyor nonushtalar","ru":"Готовые завтраки","en":"Breakfast cereals"}', '{"uz":"Kunni tez va to‘yimli boshlash","ru":"Быстрое и питательное начало дня","en":"A quick, filling start to the day"}', '{"uz":"Tayyor nonushtalar — kunni tez boshlashning to‘yimli yo‘li. Qarsillab turuvchi makkajo‘xori donalari sut yoki yogurt bilan bir zumda tayyor bo‘ladi.","ru":"Готовые завтраки — быстрый и питательный способ начать день. Хрустящие кукурузные изделия готовы за минуту с молоком или йогуртом.","en":"Breakfast cereals — a fast, filling way to start the day. Crisp corn pieces are ready in a minute with milk or yoghurt."}', 'assets/img/photo/hrust.jpg', 'amber', 30)
insert into products (id, cat, name, code, img, descr, composition, storage, nutrition, pack, active, sort) values
  ('sl', 'draje', 'SLADUS SL', '2.32', 'assets/img/photo/SL.jpg', '{"uz":"Glazurlangan makkajo‘xori-bug‘doy mahsuloti","ru":"Глазированные кукурузно-пшеничные изделия","en":"Glazed corn and wheat pieces"}', '{"uz":"Shakar, kakao kukuni (19,7%), o‘simlik moyi, yeryong‘oq, aromatizator, quruq sut, soya letsitini. Konfetlar 50 g flou-pak individual qadoqda va kartonda 2 kg qilib joylanadi.","ru":"Сахар-песок, какао порошок (19,7%), масло растительное, земляной орех, ароматизатор, сухое молоко, соевый лецитин. Конфеты в индивидуальной упаковке флоу-пак по 50 г и по 2 кг в картонной коробке.","en":"Sugar, cocoa powder (19.7%), vegetable oil, peanut, flavouring, milk powder, soy lecithin. Packed in 50 g flow-pack units and 2 kg cartons."}', '{"t":"18±3°C","rh":"75%"}', '{"protein":13.71,"fat":50.63,"carbs":30.77,"kcal":625}', '{"size":"31×22×12","volume":"0.0082","net":"2 kg","pcs":"40 ± 1%","tnved":"1806903100"}', true, 0),
  ('dare', 'draje', 'SLADUS DARE', '2.47', 'assets/img/photo/dare.jpg', '{"uz":"Kakao kukuni bilan qoplangan glazurlangan yeryong‘oq","ru":"Глазированный арахис, покрытый какао порошком","en":"Glazed peanut dusted with cocoa powder"}', '{"uz":"Bug‘doy uni, makkajo‘xori uni, guruch uni, kakao kukuni (9,3%), shakar, o‘simlik moyi, quruq sut, letsitin, tuz, vanilin. Kartonda 2 kg qilib joylanadi.","ru":"Мука пшеничная, мука кукурузная, мука рисовая, какао порошок (9,3%), сахар, масло растительное, сухое молоко, лецитин, соль, ванилин. Упакованы по 2 кг в картонной коробке.","en":"Wheat flour, corn flour, rice flour, cocoa powder (9.3%), sugar, vegetable oil, milk powder, lecithin, salt, vanillin. Packed in 2 kg cartons."}', '{"t":"+22°C","rh":"70%"}', '{"protein":9.11,"fat":27.4,"carbs":56.85,"kcal":497}', '{"size":"34×23×13","volume":"0.0093","net":"2 kg","pcs":"350 ± 3%","tnved":"1806905009"}', true, 10),
